function alternatives(answer,answers){if(reviewedAlternatives[answer])return reviewedAlternatives[answer];if(/^(기원전 )?\d+년$/.test(answer)){const n=Number(answer.match(/\d+/)[0]),prefix=answer.startsWith('기원전 ')?'기원전 ':'';return [prefix+(n-8)+'년',prefix+(n+12)+'년'];}const pool=choicePools.find(p=>p.includes(answer));if(pool)return pool.filter(x=>x!==answer).slice(0,2);throw Error('Missing reviewed distractors: '+answer);}

function card(bankId,title,rows,source){if(rows.length!==5)throw Error('Five distinct questions required: '+title);const b=banks.find(b=>b.id===bankId);if(!b)throw Error('Unknown history lesson '+bankId);const group=bankId+'-reading-'+(cards.filter(c=>c.bankId===bankId).length+1),answers=rows.map(r=>r[0]);if(new Set(answers).size!==5)throw Error('Repeated answer in '+title);const passage=rows.map(r=>r[2]).join(' ');rows.forEach(([answer,prompt,explanation],i)=>b.items.push({evidenceId:group+'-'+(i+1),historyVolume:true,passageId:group,passageTitle:title,detail:passage,prompt,answer,choices:[answer,...alternatives(answer,answers)],explanation,source:source||sources[bankId.startsWith('goryeo')?'goryeo':['paleolithic','neolithic','bronze-age','gojoseon'].includes(bankId)?'pre':'ancient'],sourceLabel:'국사편찬위원회 · 역사 읽기 참고'}));cards.push({bankId,id:group,title});}
